//! 🧩️ Handwritten complete composite members, components and ordered action entities.
use super::En1994Snapshot;
use crate::{CompositeBeam,CompositeColumn,CompositeSlab,SteelSection,ProfiledSheeting,HeadedStuds,CharacteristicAction,ColumnAction,document::AnnexChoice};
use std::collections::BTreeMap;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SnapshotEncoding,SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,validate_sqlite_database_schema,artifact::{Cell,FloatColumn,FloatRow,NativeEncodingBound,RowWriter,reconstruct_text}}};
use semio_framework_value::{ValueError, ValueRefusalKind};
fn invalid(message: impl Into<String>) -> ValueError { ValueError::new(ValueRefusalKind::InvalidValue, message) }

const DOCUMENT:&[FloatColumn]=&[FloatColumn::Binary64(3),FloatColumn::Binary64(5)];
const BEAM:&[FloatColumn]=&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14),FloatColumn::Binary64(15),FloatColumn::Binary64(16)];
const STEEL:&[FloatColumn]=&[FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10)];
const SHEETING:&[FloatColumn]=&[FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5)];
const STUDS:&[FloatColumn]=&[FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(6)];
const ACTION:&[FloatColumn]=&[FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10)];
const COLUMN:&[FloatColumn]=&[FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14)];
const COLUMN_ACTION:&[FloatColumn]=&[FloatColumn::Binary64(7),FloatColumn::Binary64(8)];
const SLAB:&[FloatColumn]=&[FloatColumn::Binary64(4),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10)];
type Entities<'a>=BTreeMap<i64,FloatRow<'a>>;
type Groups<'a>=BTreeMap<i64,Vec<FloatRow<'a>>>;
fn annex(value:AnnexChoice)-> &'static str{match value{AnnexChoice::En=>"En",AnnexChoice::De=>"De"}}
fn read_annex(value:&str)->Result<AnnexChoice, ValueError>{match value{"En"=>Ok(AnnexChoice::En),"De"=>Ok(AnnexChoice::De),_=>Err(invalid("EN1994 unsupported annex"))}}
fn boolean(row:FloatRow<'_>,column:usize)->Result<bool, ValueError>{match row.integer(column)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("EN1994 requires a boolean integer"))}}
fn unsigned(row:FloatRow<'_>,column:usize)->Result<u32, ValueError>{u32::try_from(row.integer(column)?).map_err(|error| invalid(error.to_string()))}
fn ordinal(value:usize)->Result<Cell<'static>, ValueError>{Ok(Cell::Integer(i64::try_from(value).map_err(|error| invalid(error.to_string()))?))}
fn checkpoint(control:&mut SqliteSnapshotControl<'_>,position:usize,total:usize)->Result<(), ValueError>{if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,total)?;}Ok(())}
fn entities<'a>(database:&'a SqliteDatabase,table:&str,columns:usize,floats:&'static[FloatColumn],control:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>, ValueError>{let rows=&database.table(table)?.rows;let mut result=Entities::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let row=FloatRow::new(row,floats)?;if row.values.len()!=columns||row.rowid<=0||row.integer(0)?!=row.rowid||result.insert(row.rowid,row).is_some(){return Err(invalid(format!("{table} requires exact fields and unique positive aliased identities")));}}Ok(result)}
fn groups<'a>(rows:&Entities<'a>,parents:&Entities<'a>,control:&mut SqliteSnapshotControl<'_>)->Result<Groups<'a>, ValueError>{let mut grouped:BTreeMap<i64,BTreeMap<usize,FloatRow<'a>>>=BTreeMap::new();for(position,row)in rows.values().copied().enumerate(){checkpoint(control,position,rows.len())?;let parent=row.integer(1)?;let ordinal=usize::try_from(row.integer(2)?).map_err(|error| invalid(error.to_string()))?;if !parents.contains_key(&parent)||grouped.entry(parent).or_default().insert(ordinal,row).is_some(){return Err(invalid("EN1994 foreign parent or duplicate ordinal"));}}let mut result=Groups::new();for(parent,siblings)in grouped{for(position,ordinal)in siblings.keys().copied().enumerate(){checkpoint(control,position,siblings.len())?;if position!=ordinal{return Err(invalid("EN1994 ordinals must be dense"));}}result.insert(parent,siblings.into_values().collect());}Ok(result)}
fn owned(rows:&Entities<'_>,parents:&Entities<'_>,control:&mut SqliteSnapshotControl<'_>)->Result<(), ValueError>{if rows.len()!=parents.len(){return Err(invalid("EN1994 mandatory member record count differs"));}for(position,row)in rows.values().enumerate(){checkpoint(control,position,rows.len())?;if !parents.contains_key(&row.rowid)||row.integer(1)?!=row.rowid{return Err(invalid("EN1994 mandatory record identity differs from owner"));}}Ok(())}
fn siblings<'a>(groups:&'a Groups<'a>,parent:i64)-> &'a[FloatRow<'a>]{groups.get(&parent).map(Vec::as_slice).unwrap_or_default()}
fn sheeting(out:&mut RowWriter<'_,'_>,table:&str,parent:i64,value:&ProfiledSheeting)->Result<(), ValueError>{out.insert_key_float(table,parent,&[Cell::Integer(parent),Cell::Text(&value.profile),Cell::Real(value.height_m),Cell::Real(value.rib_width_m),Cell::Real(value.thickness_m),Cell::Integer(i64::from(value.ribs_parallel_to_beam))],SHEETING)?;Ok(())}
fn actions(out:&mut RowWriter<'_,'_>,table:&str,parent:i64,values:&[CharacteristicAction])->Result<(), ValueError>{for(position,value)in values.iter().enumerate(){out.insert_float(table,&[Cell::Integer(parent),ordinal(position)?,Cell::Text(&value.id),Cell::Text(&value.kind),Cell::Text(&value.category),Cell::Text(&value.stage),Cell::Real(value.q_area_pa),Cell::Real(value.f_k_n),Cell::Real(value.delta_sigma_k_pa),Cell::Real(value.delta_tau_k_pa)],ACTION)?;}Ok(())}
fn read_sheeting(row:FloatRow<'_>,control:&mut SqliteSnapshotControl<'_>)->Result<ProfiledSheeting, ValueError>{Ok(ProfiledSheeting{profile:reconstruct_text(control,row.text(2)?)?,height_m:row.real(3)?,rib_width_m:row.real(4)?,thickness_m:row.real(5)?,ribs_parallel_to_beam:boolean(row,6)?})}
fn read_actions(rows:&[FloatRow<'_>],control:&mut SqliteSnapshotControl<'_>)->Result<Vec<CharacteristicAction>, ValueError>{let mut result=Vec::new();for row in rows{checkpoint(control,result.len(),rows.len())?;result.push(CharacteristicAction{id:reconstruct_text(control,row.text(3)?)?,kind:reconstruct_text(control,row.text(4)?)?,category:reconstruct_text(control,row.text(5)?)?,stage:reconstruct_text(control,row.text(6)?)?,q_area_pa:row.real(7)?,f_k_n:row.real(8)?,delta_sigma_k_pa:row.real(9)?,delta_tau_k_pa:row.real(10)?});}Ok(result)}
fn bound_sheeting(bound:&mut NativeEncodingBound<'_,'_>,value:&ProfiledSheeting)->Result<(), ValueError>{bound.add(16384)?;bound.repeated(value.profile.len(),24)}
fn bound_actions(bound:&mut NativeEncodingBound<'_,'_>,values:&[CharacteristicAction])->Result<(), ValueError>{for value in values{bound.add(16384)?;for text in [&value.id,&value.kind,&value.category,&value.stage]{bound.repeated(text.len(),24)?;}}Ok(())}


impl En1994Snapshot {
    fn write_sqlite_rows(&self, out: &mut RowWriter<'_,'_>) -> Result<(), ValueError> {
        out.insert_key_float("en1994_document",1,&[Cell::Text(annex(self.annex)),Cell::Text(&self.structure_kind),Cell::Real(self.steel_f_y_pa),Cell::Text(&self.fire_rating),Cell::Real(self.insulation_thickness_m),Cell::Text(&self.fatigue_detail)],DOCUMENT)?;
  for(position,b)in self.beams.iter().enumerate(){let parent=out.insert_float("en1994_beam",&[Cell::Integer(1),ordinal(position)?,Cell::Text(&b.id),Cell::Real(b.span_m),Cell::Real(b.spacing_m),Cell::Text(&b.support),Cell::Text(&b.construction),Cell::Real(b.slab_thickness_m),Cell::Real(b.concrete_f_ck_pa),Cell::Real(b.concrete_e_cm_pa),Cell::Real(b.transverse_as_m2_per_m),Cell::Real(b.ltb_length_m),Cell::Real(b.as_hogging_m2_per_m),Cell::Real(b.bar_spacing_m),Cell::Real(b.wk_limit_m),Cell::Real(b.n_cycles)],BEAM)?;let s=&b.steel;out.insert_key_float("en1994_beam_steel",parent,&[Cell::Integer(parent),Cell::Text(&s.designation),Cell::Real(s.height_m),Cell::Real(s.width_m),Cell::Real(s.tw_m),Cell::Real(s.tf_m),Cell::Real(s.a_m2),Cell::Real(s.w_pl_y_m3),Cell::Real(s.i_y_m4),Cell::Real(s.a_v_m2)],STEEL)?;sheeting(out,"en1994_beam_sheeting",parent,&b.sheeting)?;let t=&b.studs;out.insert_key_float("en1994_beam_studs",parent,&[Cell::Integer(parent),Cell::Real(t.diameter_m),Cell::Real(t.height_m),Cell::Real(t.f_u_pa),Cell::Integer(i64::from(t.count_per_rib)),Cell::Real(t.spacing_m),Cell::Integer(i64::from(t.total_count))],STUDS)?;actions(out,"en1994_beam_action",parent,&b.actions)?;}
  for(position,c)in self.columns.iter().enumerate(){let parent=out.insert_float("en1994_column",&[Cell::Integer(1),ordinal(position)?,Cell::Text(&c.id),Cell::Text(&c.kind),Cell::Real(c.length_m),Cell::Real(c.outer_size_m),Cell::Real(c.wall_thickness_m),Cell::Real(c.steel_a_m2),Cell::Real(c.steel_f_y_pa),Cell::Real(c.concrete_a_m2),Cell::Real(c.concrete_f_ck_pa),Cell::Real(c.reinforcement_as_m2),Cell::Real(c.reinforcement_f_yk_pa),Cell::Real(c.i_m4),Cell::Text(&c.buckling_curve)],COLUMN)?;for(ordinal_value,a)in c.actions.iter().enumerate(){out.insert_float("en1994_column_action",&[Cell::Integer(parent),ordinal(ordinal_value)?,Cell::Text(&a.id),Cell::Text(&a.kind),Cell::Text(&a.category),Cell::Text(&a.stage),Cell::Real(a.n_k_n),Cell::Real(a.m_k_nm)],COLUMN_ACTION)?;}}
  for(position,s)in self.slabs.iter().enumerate(){let parent=out.insert_float("en1994_slab",&[Cell::Integer(1),ordinal(position)?,Cell::Text(&s.id),Cell::Real(s.span_m),Cell::Text(&s.support),Cell::Real(s.concrete_thickness_m),Cell::Real(s.f_ck_pa),Cell::Real(s.m_factor),Cell::Real(s.k_factor),Cell::Real(s.as_m2_per_m)],SLAB)?;sheeting(out,"en1994_slab_sheeting",parent,&s.sheeting)?;actions(out,"en1994_slab_action",parent,&s.actions)?;}
        Ok(())
    }
    fn admit_sqlite_values(&self, control: &mut SqliteSnapshotControl<'_>, phase: SqliteSnapshotPhase) -> Result<(), ValueError> { let mut out = RowWriter::borrowed(control, phase)?; self.write_sqlite_rows(&mut out)?; out.finish_borrowed() }
}
impl ArtifactSqliteSnapshot for En1994Snapshot{
 fn decode_sqlite_snapshot_native(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self, ValueError>{let snapshot=store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|record, native| Self::__dsl_from_record_controlled(record, native),control)?;snapshot.admit_sqlite_values(control,SqliteSnapshotPhase::DecodeNative)?;Ok(snapshot)}
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload, ValueError>{
  control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;let add=|count:usize,size:usize|count.checked_add(size).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "Native semantic row count overflow"));let mut rows=1usize;rows=add(rows,self.beams.len().checked_mul(4).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "EN1994 beam row count overflow"))?)?;rows=add(rows,self.columns.len())?;rows=add(rows,self.slabs.len().checked_mul(2).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "EN1994 slab row count overflow"))?)?;control.check_rows(rows)?;for(index,beam)in self.beams.iter().enumerate(){rows=add(rows,beam.actions.len())?;control.check_rows(rows)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,self.beams.len())?}}for(index,column)in self.columns.iter().enumerate(){rows=add(rows,column.actions.len())?;control.check_rows(rows)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,self.columns.len())?}}for(index,slab)in self.slabs.iter().enumerate(){rows=add(rows,slab.actions.len())?;control.check_rows(rows)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,self.slabs.len())?}}
  self.admit_sqlite_values(control,SqliteSnapshotPhase::EncodeNative)?;
  store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),control)
 }

 fn preflight_sqlite_snapshot_encoding(&self,_:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(), ValueError>{
  let mut bound=NativeEncodingBound::new(control)?;bound.add(16384)?;for text in [&self.structure_kind,&self.fire_rating,&self.fatigue_detail]{bound.repeated(text.len(),24)?;}
  for beam in &self.beams{bound.add(3*16384)?;for text in [&beam.id,&beam.support,&beam.construction,&beam.steel.designation]{bound.repeated(text.len(),24)?;}bound_sheeting(&mut bound,&beam.sheeting)?;bound_actions(&mut bound,&beam.actions)?;}
  for column in &self.columns{bound.add(16384)?;for text in [&column.id,&column.kind,&column.buckling_curve]{bound.repeated(text.len(),24)?;}for action in &column.actions{bound.add(16384)?;for text in [&action.id,&action.kind,&action.category,&action.stage]{bound.repeated(text.len(),24)?;}}}
  for slab in &self.slabs{bound.add(16384)?;for text in [&slab.id,&slab.support]{bound.repeated(text.len(),24)?;}bound_sheeting(&mut bound,&slab.sheeting)?;bound_actions(&mut bound,&slab.actions)?;}bound.finish()
 }
    fn to_sqlite_database(&self, control: &mut SqliteSnapshotControl<'_>) -> Result<SqliteDatabase, ValueError> { let mut out = RowWriter::new(Self::SQLITE_SCHEMA, control)?; self.write_sqlite_rows(&mut out)?; out.finish() }

 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self, ValueError>{
  validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;
  let documents=entities(database,"en1994_document",7,DOCUMENT,control)?;if documents.len()!=1||!documents.contains_key(&1){return Err(invalid("EN1994 requires document identity one"));}let d=documents[&1];
  let beam_rows=entities(database,"en1994_beam",17,BEAM,control)?;let steel_rows=entities(database,"en1994_beam_steel",11,STEEL,control)?;let beam_sheets=entities(database,"en1994_beam_sheeting",7,SHEETING,control)?;let stud_rows=entities(database,"en1994_beam_studs",8,STUDS,control)?;let beam_action_rows=entities(database,"en1994_beam_action",11,ACTION,control)?;let column_rows=entities(database,"en1994_column",16,COLUMN,control)?;let column_action_rows=entities(database,"en1994_column_action",9,COLUMN_ACTION,control)?;let slab_rows=entities(database,"en1994_slab",11,SLAB,control)?;let slab_sheets=entities(database,"en1994_slab_sheeting",7,SHEETING,control)?;let slab_action_rows=entities(database,"en1994_slab_action",11,ACTION,control)?;
  owned(&steel_rows,&beam_rows,control)?;owned(&beam_sheets,&beam_rows,control)?;owned(&stud_rows,&beam_rows,control)?;owned(&slab_sheets,&slab_rows,control)?;
  let beam_groups=groups(&beam_rows,&documents,control)?;let beam_actions=groups(&beam_action_rows,&beam_rows,control)?;let column_groups=groups(&column_rows,&documents,control)?;let column_actions=groups(&column_action_rows,&column_rows,control)?;let slab_groups=groups(&slab_rows,&documents,control)?;let slab_actions=groups(&slab_action_rows,&slab_rows,control)?;
  let mut beams=Vec::new();for b in siblings(&beam_groups,1){checkpoint(control,beams.len(),beam_rows.len())?;let s=steel_rows[&b.rowid];let t=stud_rows[&b.rowid];beams.push(CompositeBeam{id:reconstruct_text(control,b.text(3)?)?,span_m:b.real(4)?,spacing_m:b.real(5)?,support:reconstruct_text(control,b.text(6)?)?,construction:reconstruct_text(control,b.text(7)?)?,slab_thickness_m:b.real(8)?,concrete_f_ck_pa:b.real(9)?,concrete_e_cm_pa:b.real(10)?,transverse_as_m2_per_m:b.real(11)?,ltb_length_m:b.real(12)?,as_hogging_m2_per_m:b.real(13)?,bar_spacing_m:b.real(14)?,wk_limit_m:b.real(15)?,n_cycles:b.real(16)?,steel:SteelSection{designation:reconstruct_text(control,s.text(2)?)?,height_m:s.real(3)?,width_m:s.real(4)?,tw_m:s.real(5)?,tf_m:s.real(6)?,a_m2:s.real(7)?,w_pl_y_m3:s.real(8)?,i_y_m4:s.real(9)?,a_v_m2:s.real(10)?},sheeting:read_sheeting(beam_sheets[&b.rowid],control)?,studs:HeadedStuds{diameter_m:t.real(2)?,height_m:t.real(3)?,f_u_pa:t.real(4)?,count_per_rib:unsigned(t,5)?,spacing_m:t.real(6)?,total_count:unsigned(t,7)?},actions:read_actions(siblings(&beam_actions,b.rowid),control)?});}
  let mut columns=Vec::new();for c in siblings(&column_groups,1){checkpoint(control,columns.len(),column_rows.len())?;let mut actions=Vec::new();for a in siblings(&column_actions,c.rowid){checkpoint(control,actions.len(),0)?;actions.push(ColumnAction{id:reconstruct_text(control,a.text(3)?)?,kind:reconstruct_text(control,a.text(4)?)?,category:reconstruct_text(control,a.text(5)?)?,stage:reconstruct_text(control,a.text(6)?)?,n_k_n:a.real(7)?,m_k_nm:a.real(8)?});}columns.push(CompositeColumn{id:reconstruct_text(control,c.text(3)?)?,kind:reconstruct_text(control,c.text(4)?)?,length_m:c.real(5)?,outer_size_m:c.real(6)?,wall_thickness_m:c.real(7)?,steel_a_m2:c.real(8)?,steel_f_y_pa:c.real(9)?,concrete_a_m2:c.real(10)?,concrete_f_ck_pa:c.real(11)?,reinforcement_as_m2:c.real(12)?,reinforcement_f_yk_pa:c.real(13)?,i_m4:c.real(14)?,buckling_curve:reconstruct_text(control,c.text(15)?)?,actions});}
  let mut slabs=Vec::new();for s in siblings(&slab_groups,1){checkpoint(control,slabs.len(),slab_rows.len())?;slabs.push(CompositeSlab{id:reconstruct_text(control,s.text(3)?)?,span_m:s.real(4)?,support:reconstruct_text(control,s.text(5)?)?,concrete_thickness_m:s.real(6)?,f_ck_pa:s.real(7)?,m_factor:s.real(8)?,k_factor:s.real(9)?,as_m2_per_m:s.real(10)?,sheeting:read_sheeting(slab_sheets[&s.rowid],control)?,actions:read_actions(siblings(&slab_actions,s.rowid),control)?});}
  let snapshot=Self{annex:read_annex(d.text(1)?)?,structure_kind:reconstruct_text(control,d.text(2)?)?,steel_f_y_pa:d.real(3)?,fire_rating:reconstruct_text(control,d.text(4)?)?,insulation_thickness_m:d.real(5)?,fatigue_detail:reconstruct_text(control,d.text(6)?)?,beams,columns,slabs};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)?;Ok(snapshot)
 }
}
pub fn sqlite_codec()->store::ArtifactSqliteSnapshotCodec{<En1994Snapshot as store::ArtifactSqliteSnapshot>::sqlite_codec()}
